const body = $json.body || $json;
const event = body.event || body;
const normalized = {
  level: event.level || 'INFO',
  client_id: event.client_id || 'unknown',
  workflow_name: event.workflow_name || 'unknown',
  agent: event.agent || 'unknown',
  source: event.source || null,
  content_id: event.content_id || null,
  action: event.action || null,
  model: event.model || null,
  tokens: Number(event.tokens || 0),
  estimated_cost: Number(event.estimated_cost || 0),
  duration_ms: Number(event.duration_ms || 0),
  score: Number(event.score || 0),
  approval_status: event.approval_status || null,
  error_message: event.error_message || null,
  metadata: event.metadata || event
};
return [{ json: normalized }];
